SELECT s.id, s.symbol, s.interval_code, s.candle_open_time, s.generated_at, s.created_at, s.decision, s.original_decision, s.total_score, s.confidence_score, s.effective_confidence_score, s.final_entry_allowed, s.primary_blocking_stage, s.data_quality_valid, s.market_regime, s.market_regime_confidence, s.selected_strategy, s.strategy_entry_allowed, s.entry_authority, s.confluence_status, s.confluence_higher_interval, s.confluence_higher_decision, s.btc_context_status, s.btc_context_entry_allowed, s.btc_context_age_seconds, s.latest_price, s.stop_loss, s.take_profit, s.atr_percent, s.risk_reward_ratio, s.volatility_level, s.atr_overextended, LEFT(s.final_decision_explanation,800) AS final_expl FROM trade_signal s WHERE s.id IN (176710,171589,167668,165412,159408,156723) ORDER BY s.id